import { expect, expectStatus, test } from "../../fixtures";

interface DocumentBody {
  id: string;
  vendor_id: string;
  kind: string;
  status: "processing" | "extracted" | "failed";
}

interface ExtractionBody {
  id: string;
  document_id: string;
  kind: string;
  fields: Record<string, { value: string | null; confidence: number }>;
  status: string;
}

test.describe("upload vendor documents", () => {
  test(
    "fields that cannot be parsed get low confidence",
    { tag: "@DOC-03" },
    async ({ apiAs }) => {
      // Arrange: a signed-in member and a draft vendor with a unique name and email.
      const member = await apiAs("member");
      const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

      const vendorResponse = await member.post("/api/vendors", {
        data: {
          name: `Doc Vendor ${suffix}`,
          category: "services",
          contact_email: `doc-vendor-${suffix}@example.test`,
        },
      });
      const vendor = await expectStatus<{ id: string; status: string }>(vendorResponse, 201);
      expect(vendor.status).toBe("draft");

      // Act: upload an insurance certificate whose expiry date is unparseable.
      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: `certificate-${suffix}.txt`,
            mimeType: "text/plain",
            buffer: Buffer.from(
              `Certificate of Insurance\nPolicy expiry date: next spring\nInsured: Doc Vendor ${suffix}\n`,
            ),
          },
        },
      });
      const document = await expectStatus<DocumentBody>(uploadResponse, 201);
      expect(document.vendor_id).toBe(vendor.id);
      expect(document.kind).toBe("insurance_certificate");

      // Wait for background processing to finish.
      await expect
        .poll(
          async () => {
            const response = await member.get(`/api/documents/${document.id}`);
            return (await expectStatus<DocumentBody>(response, 200)).status;
          },
          { timeout: 60_000, intervals: [500, 1_000, 2_000] },
        )
        .not.toBe("processing");

      // Assert: the extraction is reachable and the expiry_date field is unparsed with low confidence.
      const extractionResponse = await member.get(`/api/documents/${document.id}/extraction`);
      const extraction = await expectStatus<ExtractionBody>(extractionResponse, 200);
      expect(extraction.document_id).toBe(document.id);

      const expiry = extraction.fields["expiry_date"];
      expect(expiry).toBeDefined();
      expect(expiry.value).toBeNull();
      expect(expiry.confidence).toBeLessThan(0.5);
    },
  );
});
